#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

# --- this wizard's own helpers (PowerShell bridge) ───────────────────────
#
# The machine-level half of this procedure is Windows-native (Credential
# Manager, persistent user env vars), so we shell out to PowerShell even when
# the wizard itself runs under Git Bash or WSL.

if   command -v pwsh           >/dev/null 2>&1; then PS="pwsh"
elif command -v powershell.exe >/dev/null 2>&1; then PS="powershell.exe"
elif command -v powershell     >/dev/null 2>&1; then PS="powershell"
else PS=""
fi

# _gh_reachable: can this machine open a TCP/HTTPS connection to github.com?
_gh_reachable() {
  [[ -n "$PS" ]] || return 1
  "$PS" -NoProfile -NonInteractive -Command \
    "try { Invoke-WebRequest 'https://github.com' -Method Head -TimeoutSec 12 -UseBasicParsing -ErrorAction Stop | Out-Null; exit 0 } catch { exit 1 }" \
    >/dev/null 2>&1
}

# _read_gcm_token: pull the GitHub credential Git Credential Manager stored in
# Windows Credential Manager. Blobs are UTF-8 (not UTF-16) — decoding them as
# UTF-16 yields mojibake and a bogus "invalid token" verdict.
_read_gcm_token() {
  [[ -n "$PS" ]] || return 1
  "$PS" -NoProfile -NonInteractive -Command - <<'PSEOF' 2>/dev/null | tr -d '\r\n'
$sig = @'
using System;
using System.Runtime.InteropServices;
public class CredWiz {
  [DllImport("advapi32.dll", SetLastError=true, CharSet=CharSet.Unicode)]
  public static extern bool CredRead(string target, int type, int flags, out IntPtr credential);
  [DllImport("advapi32.dll")] public static extern void CredFree(IntPtr cred);
  [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)]
  public struct CREDENTIAL {
    public int Flags; public int Type; public string TargetName; public string Comment;
    public long LastWritten; public int CredentialBlobSize; public IntPtr CredentialBlob;
    public int Persist; public int AttributeCount; public IntPtr Attributes;
    public string TargetAlias; public string UserName;
  }
  public static string Get(string target) {
    IntPtr p;
    if (!CredRead(target, 1, 0, out p)) return null;
    try {
      CREDENTIAL c = (CREDENTIAL)Marshal.PtrToStructure(p, typeof(CREDENTIAL));
      byte[] b = new byte[c.CredentialBlobSize];
      Marshal.Copy(c.CredentialBlob, b, 0, c.CredentialBlobSize);
      return System.Text.Encoding.UTF8.GetString(b);
    } finally { CredFree(p); }
  }
}
'@
Add-Type -TypeDefinition $sig -Language CSharp -ErrorAction SilentlyContinue
foreach ($t in 'GitHub - https://api.github.com/zxd15978684198','git:https://github.com') {
  $v = [CredWiz]::Get($t)
  if ($v) { $v.Trim(); break }
}
PSEOF
}

# _token_valid TOKEN: does api.github.com accept it? (token passed via env,
# never argv, so it stays out of the process list.)
_token_valid() {
  [[ -n "$PS" ]] || return 1
  WIZ_TOKEN="$1" "$PS" -NoProfile -NonInteractive -Command \
    "try { Invoke-RestMethod 'https://api.github.com/user' -Headers @{ Authorization = \"token \$env:WIZ_TOKEN\"; 'User-Agent' = 'gh-wizard' } -TimeoutSec 25 -ErrorAction Stop | Out-Null; exit 0 } catch { exit 1 }" \
    >/dev/null 2>&1
}

# _persist_gh_token TOKEN: write GH_TOKEN as a persistent *user* env var.
_persist_gh_token() {
  [[ -n "$PS" ]] || return 1
  WIZ_TOKEN="$1" "$PS" -NoProfile -NonInteractive -Command \
    "[Environment]::SetEnvironmentVariable('GH_TOKEN', \$env:WIZ_TOKEN, 'User')" \
    >/dev/null 2>&1
}

banner "GitHub CLI 认证 · github.com 受限网络"

# ── Stage 1: preflight ────────────────────────────────────────────────────
stage "1/4 前置检查"
say "先确认 gh 已安装，并判断这台机器能不能直连 github.com。"
say ""

if ! command -v gh >/dev/null 2>&1; then
  warn "PATH 里找不到 gh。"
  note "已安装的位置: C:\\Program Files\\GitHub CLI\\gh.exe"
  note "请重开一个终端让 PATH 生效，然后再运行本向导。"
  exit 1
fi
note "gh: $(gh --version | head -n1)"

if [[ -z "$PS" ]]; then
  warn "找不到 PowerShell —— 路径 B（读已存凭据）会不可用。"
fi

NET_OK=0
if _gh_reachable; then
  NET_OK=1
  note "github.com: 可达 ✓"
else
  note "github.com: 不可达（直连超时）✗"
fi

say ""
note "说明：gh 的“设备授权码”登录第一跳就要打 github.com。"
note "这台机器上 github.com 被阻断，而 api.github.com 是通的 —— 所以两条路差别很大。"
pause "继续？"

# ── Stage 2: choose the path ──────────────────────────────────────────────
stage "2/4 选择认证路径"

if [[ "$NET_OK" == "1" ]]; then
  say "github.com 现在通的，走标准登录即可，权限完整。"
  note "这条路径同时让 git clone / push 正常工作。"
  AUTH_PATH="A"
  pause "按 Enter 开始标准登录"
else
  say "github.com 直连不通，两条路可选："
  say ""
  step "路径 A —— 先把代理打开（本机是 kuaiya），让 github.com 通，再走标准登录。"
  note "   权限最全（含 read:org），git 也能用。推荐。"
  step "路径 B —— 复用本机已存的 GitHub 凭据作为 GH_TOKEN。"
  note "   立刻可用，不需要代理；但权限只有 repo / user / workflow，缺 read:org。"
  say ""
  if confirm "先试路径 A（去打开代理）吗？"; then
    AUTH_PATH="A"
  else
    AUTH_PATH="B"
  fi
fi

# ── Stage 3: perform the authentication ───────────────────────────────────
stage "3/4 执行认证"

if [[ "$AUTH_PATH" == "A" && "$NET_OK" != "1" ]]; then
  say "请现在打开代理软件（kuaiya），确认系统代理已开启。"
  note "本机代理端口应为 127.0.0.1:20561 —— 下面会检查它是否真的开始监听。"
  pause "开好了按 Enter，重新探测"

  if "$PS" -NoProfile -NonInteractive -Command \
       "if (Get-NetTCPConnection -State Listen -LocalPort 20561 -ErrorAction SilentlyContinue) { exit 0 } else { exit 1 }" \
       >/dev/null 2>&1; then
    note "端口 20561: 已监听 ✓"
  else
    warn "端口 20561 还是没监听 —— 代理软件在跑，但代理本身没生效。"
  fi

  if _gh_reachable; then
    NET_OK=1
    note "github.com: 可达 ✓"
  else
    warn "github.com 仍不通。若继续走路径 A，登录会卡在授权码那一步。"
    if ! confirm "仍要继续走路径 A 吗？"; then
      AUTH_PATH="B"
      note "已切到路径 B。"
    fi
  fi
fi

if [[ "$AUTH_PATH" == "A" ]]; then
  say "接下来 gh 会显示一个一次性授权码，并在浏览器打开授权页。"
  step "把终端显示的码填进网页，点 Authorize。"
  say ""
  pause "准备好了按 Enter —— gh 现在接管交互登录"
  gh auth login --hostname github.com --git-protocol https --web || true
else
  say "从 Windows 凭据管理器读取已存的 GitHub 凭据（不会回显到屏幕）。"
  TOKEN="$(_read_gcm_token || true)"

  if [[ -n "$TOKEN" ]]; then
    note "读到 token：${TOKEN:0:4}…（长度 ${#TOKEN}）"
  else
    warn "没读到已存凭据。"
    note "可在此处粘贴一个 token，或在别处创建后回来重跑。"
    ask_secret TOKEN "粘贴 GitHub token（留空则跳过）："
  fi

  if [[ -z "$TOKEN" ]]; then
    warn "没有 token，无法继续。"
    exit 1
  fi

  case "$TOKEN" in
    gho_*|ghp_*|ghu_*|ghs_*|ghr_*|github_pat_*) note "token 格式看起来正常。" ;;
    *) warn "这不像标准的 GitHub token 前缀，但仍会尝试验证。" ;;
  esac

  say ""
  say "先用 api.github.com 验一次，避免把废 token 写进环境变量。"
  if _token_valid "$TOKEN"; then
    note "token 有效 ✓"
    if _persist_gh_token "$TOKEN"; then
      export GH_TOKEN="$TOKEN"
      note "已写入用户环境变量 GH_TOKEN（新开终端生效；当前终端已临时生效）。"
    else
      warn "写入用户环境变量失败。"
      SKIPPED+=("把 GH_TOKEN 写入用户环境变量")
    fi
  else
    warn "token 无效（api.github.com 拒绝）。已中止，未写入任何配置。"
    note "多半是这份凭据已过期 —— 需要走路径 A 重新登录。"
    exit 1
  fi
fi

# ── Stage 4: verify ───────────────────────────────────────────────────────
stage "4/4 验证"
say "跑几条真实命令确认状态："
say ""

printf '  %s$ gh auth status%s\n' "$DIM" "$RESET"
gh auth status 2>&1 | sed 's/^/    /' || true

say ""
printf '  %s$ gh api user --jq .login%s\n' "$DIM" "$RESET"
gh api user --jq .login 2>&1 | sed 's/^/    /' || true

say ""
printf '  %s$ gh repo list --limit 3%s\n' "$DIM" "$RESET"
gh repo list --limit 3 2>&1 | sed 's/^/    /' || true

say ""
if gh auth status 2>&1 | grep -q "Missing required token scopes"; then
  warn "当前登录缺少 read:org —— 影响与组织相关的命令。"
  SKIPPED+=("补齐 read:org：代理通了以后运行 gh auth refresh -h github.com --scopes read:org")
fi

SKIPPED+=("git clone / push 到 github.com 仍需代理（github.com 直连被阻断）")

say ""
pause "看完了按 Enter 收尾（上面的验证输出会被清屏）"

finish
